def solution(dot):
    onetwothree = range(1, 4)
    for i in onetwothree:
        d1 = (dot[i][0] - dot[0][0]) / (dot[i][1] - dot[0][1])
        a, b = [j for j in onetwothree if j != i]
        d2 = (dot[a][0] - dot[b][0]) / (dot[a][1] - dot[b][1])
        if d1 == d2:
            return 1
    return 0

