def solution(board):
    n = len(board)
    danger = [(i, j) for i in range(-1, 2) for j in range(-1, 2) if i or j]
    for i in range(n):
        for j in range(n):
            if board[i][j] == 1:
                for di, dj in danger:
                    if 0 <= i + di < n and 0 <= j + dj < n and board[i + di][j + dj] == 0:
                        board[i + di][j + dj] = 2
    return sum(1 for i in range(n) for j in range(n) if board[i][j] == 0)

