from math import ceil
def solution(n, stations, w):
    answer = 0
    ap = 1
    for st in stations:
        if st - w > ap:
            aparts = st - w - ap
            answer += ceil(aparts / (2 * w + 1))
        ap = st + w + 1
    if ap <= n:
        aparts = n - ap + 1
        answer += ceil(aparts / (2 * w + 1))
    return answer
